import * as M from './model.js';
import * as People from './community-life.js';
import * as A from './academic-year.js';
import * as Staff from './staff-work.js';
export const CITIES=['새뜰시','온빛시','솔바람군','해솔군'];
export function schools(){return ['newtown','city','oldtown','industrial','rural','mountain','coast','island'].map((region,i)=>({id:'school-'+i,name:M.REGIONS[region].school,city:CITIES[Math.floor(i/2)],region,classes:M.REGIONS[region].classes,capacity:M.REGIONS[region].count,auditCycle:3+i%3,lastAudit:2027+i%3,leading:['사회정서','AI·디지털','독서','진로','생태환경','기초학력','예술','학생자치'][i],projectEnd:2031}));}
export function data(s){return s.career??={schema:1,schoolId:schools().find(x=>x.region===s.config.region).id,schools:schools(),history:[],archives:[],gradeMode:'direct',jobMode:'mixed',job:s.teacher.skills[0].name,post:'담당',activeSkills:s.teacher.skills.map(x=>x.name),handover:null,reunions:{}};}
export function options(s,patch){const d=data(s);for(const key of ['gradeMode','jobMode'])if(['direct','relations','mixed'].includes(patch[key]))d[key]=patch[key];if(M.SKILLS.includes(patch.job))d.job=patch.job;if(['담당','부장'].includes(patch.post))d.post=patch.post;if(Array.isArray(patch.activeSkills)){const list=[...new Set(patch.activeSkills)].filter(n=>s.teacher.skills.some(x=>x.name===n));if(list.length>=1&&list.length<=4)d.activeSkills=list;}return d;}
export function offers(s){const c=data(s),year=s.academic.year+1;return c.schools.map((school,i)=>({...school,vacancies:[1+(year+i)%6,1+(year+i+2)%6],local:school.id===c.schoolId,proposal:1+(year+i+s.config.seed)%6}));}
export function propose(s,schoolId,requestedGrade,requestedJob){const c=data(s);if(!s.ended||s.day<s.academic.end)return {error:'2월 학년도 마감 후 다음 배정을 협의할 수 있습니다.'};const school=c.schools.find(x=>x.id===schoolId);if(!school)return {error:'희망 학교를 선택해 주세요.'};const offered=offers(s).find(x=>x.id===schoolId),preference=M.clamp(Number(requestedGrade)||3,1,6),relationship=M.averageTrust(s)+s.npcRelations.principal;const grade=c.gradeMode==='direct'?preference:c.gradeMode==='relations'?offered.proposal:relationship>=95?preference:offered.proposal;const job=c.jobMode==='direct'?requestedJob:c.jobMode==='relations'?M.SKILLS[(s.academic.year+s.config.seed)%M.SKILLS.length]:s.npcRelations.principal>=45?requestedJob:s.teacher.skills[0].name;if(!M.SKILLS.includes(job))return {error:'담당 업무를 선택해 주세요.'};c.handover={schoolId,grade,job,stay:schoolId===c.schoolId,sameClass:schoolId===c.schoolId&&grade===s.config.grade+1,stage:'proposal',requestedGrade:preference,created:M.stamp(s)};return {ok:true,offer:c.handover};}
export function accept(s){const c=data(s),h=c.handover;if(!h||h.stage!=='proposal')return {error:'먼저 다음 학교와 담당 학년 제안을 확인해 주세요.'};h.stage='accepted';h.accepted=M.stamp(s);return {ok:true};}
const newFirstNames=['지안','하람','은유','도하','서율','민후','유하','지온','예온','시후','다율','건호','하린','이안','소이','준희','채은','우빈','아린','도겸','나연','유찬','예나','지한','수민','태윤','서현','이든'];
export function startNext(s){const c=data(s),h=c.handover;if(!h||h.stage!=='accepted')return {error:'배정 제안을 수락하고 인계 내용을 확인해 주세요.'};People.snapshot(s);const completedYear=s.academic.year,school=c.schools.find(x=>x.id===h.schoolId);const snapshot={id:'year-'+completedYear,year:completedYear,schoolId:c.schoolId,school:A.schoolName(s),grade:s.config.grade,teacher:structuredClone(s.config),students:structuredClone(s.students),notes:structuredClone(s.notes),messages:structuredClone(s.messages.slice(-300)),npcMemories:structuredClone(s.npcMemories||{}),npcRelations:structuredClone(s.npcRelations),conversations:structuredClone(s.schoolLife.conversations),curriculum:structuredClone(s.classCurriculum),lessons:structuredClone(s.lessonResults),events:structuredClone(s.academic.events),recordReview:structuredClone(s.recordReview||null),budget:s.budget,training:structuredClone(s.staffWork?.training||[]),operations:structuredClone(s.operations||{}),support:structuredClone(s.support||{}),library:structuredClone(s.libraryLife||{}),schoolReview:structuredClone(s.schoolReview||{}),democracy:structuredClone(s.democracy||{}),staffNetwork:structuredClone(s.staffNetwork||null),sportsDay:structuredClone(s.sportsDay),inventory:structuredClone(s.inventory),created:M.stamp(s)};c.archives.push(snapshot);c.history.push({year:completedYear,school:snapshot.school,grade:s.config.grade,completedEvents:s.academic.events.filter(e=>e.status==='completed').length,lessons:s.lessonResults.length,closed:M.stamp(s)});
 const priorStudents=s.students,oldNotes=s.notes,oldNpc=s.npcRelations,skills=structuredClone(s.teacher),oldStaff=s.staffWork,settings={...c,schoolId:school.id,job:h.job,handover:null},next=M.newGame({...s.config,grade:h.grade,region:school.region,count:h.sameClass?s.students.length:school.capacity,seed:s.config.seed+103});next.teacher={...skills,energy:90,annualGrowth:0};next.teacher.strong=M.subjects(h.grade).filter(x=>skills.strong.includes(x)).concat(M.subjects(h.grade)).filter((v,i,a)=>a.indexOf(v)===i).slice(0,2);next.teacher.weak=M.subjects(h.grade).filter(x=>!next.teacher.strong.includes(x)).slice(0,2);next.career=settings;
 if(h.sameClass){next.npcMemories=structuredClone(s.npcMemories||{});next.students=next.students.map((fresh,i)=>{const old=priorStudents[i];const scores=Object.fromEntries(M.subjects(h.grade).map(sub=>[sub,old.scores[sub]??fresh.scores[sub]]));return {...fresh,...old,strong:fresh.strong,weak:fresh.weak,scores,initialScores:{...scores},records:old.records,personKey:old.personKey||'y'+completedYear+'-'+old.id};});next.notes=structuredClone(oldNotes);next.npcRelations={...oldNpc};}else{next.students.forEach((st,i)=>{st.name=st.name[0]+newFirstNames[(i+completedYear-2029)%newFirstNames.length];st.personKey='y'+(completedYear+1)+'-'+st.id;});for(const [id,n] of Object.entries(oldNotes))if(M.NPCS.some(p=>p.id===id))next.notes[id]=structuredClone(n);if(h.stay)for(const npc of M.NPCS)if(oldNpc[npc.id]!=null)next.npcRelations[npc.id]=oldNpc[npc.id];}
 next.staffNetwork={schema:1,next:s.staffNetwork?.next||0,queue:[],consultations:[],covers:[]};next.seats=next.students.map(st=>st.id);next.day=A.bounds(completedYear+1).start;if(oldStaff)next.staffWork={...oldStaff,projects:null,business:[],social:[],currentAudit:null,away:null,year:completedYear+1};for(const key of ['support','operations','libraryLife','recordReview','schoolReview','democracy'])delete s[key];A.ensure(next,true);for(const m of next.messages){m.day=next.day;m.plannerScanned=true;}Object.assign(s,next);for(const p of Object.values(s.community?.people||{}))if(p.kind==='student')p.active=false;People.data(s);M.log(s,'배정 수락·학급 기록 인계 완료 · '+A.schoolName(s)+' 첫 출근');return {ok:true};}
export function alumni(s,query=''){const q=String(query).trim();return data(s).archives.flatMap(a=>a.students.map(st=>({key:a.id+':'+st.id,archive:a,student:st,gradeNow:st.personKey&&s.students.find(x=>x.personKey===st.personKey)?s.config.grade:Math.min(7,a.grade+s.academic.year-a.year)}))).filter(x=>!q||x.student.name.includes(q)||x.archive.school.includes(q));}
export function reunion(s,key,parent=false){const item=alumni(s).find(x=>x.key===key);if(!item)return {error:'이전 인물을 찾을 수 없습니다.'};const d=data(s),person=parent?item.student.parentId:item.student.id,recordKey=key+(parent?':parent':':student'),prior=d.reunions[recordKey];if(prior?.day===s.day)return {error:'오늘 나눈 이야기는 재회 기록에 남아 있습니다.'};const memory=parent?item.archive.npcMemories?.[item.student.parentId]?.[0]:item.student.memories[0],known=typeof memory==='string'?memory:memory?.text||memory?.memory||'함께 교실에서 이야기를 나누던 시간';const line=parent?(memory?'작년 상담에서 함께 이야기했던 일이 기억나요. '+known:'안녕하세요. '+item.student.name+'의 보호자입니다. 지난 학교생활 이후의 근황을 전하고 싶었어요.'):'선생님, 저 기억하세요? '+known;const reply=parent?'그때 함께 정한 방법이 기억납니다. 그동안 어떻게 지냈는지 들려주세요.':'그때 네가 들려준 생각이 기억나. 요즘 새롭게 해 보는 일은 무엇이니?';d.reunions[recordKey]={day:s.day,date:M.stamp(s),name:item.student.name+(parent?' 보호자':''),line,reply,previous:prior||null};const notes=item.archive.notes[person]??=[];notes.unshift({text:'재회: '+reply,created:M.stamp(s)});return {ok:true,line,reply,person:person,name:d.reunions[recordKey].name};}
export function learnSkill(s,name){const c=data(s);if(!M.SKILLS.includes(name)||s.teacher.skills.some(x=>x.name===name)||s.teacher.skills.length>=6||s.teacher.annualGrowth>=2||s.teacher.skills.reduce((n,x)=>n+x.level,0)>=14)return {error:'보유 6개·총합 14·연간 성장 2 한도 안에서 새로운 스킬을 익힐 수 있습니다.'};if(!Staff.free(s,30)||M.currentSlot(s).kind!=='afternoon'||s.minute+30>1000)return {error:'수업 후 여유 시간 30분이 필요합니다.'};M.advance(s,30);s.teacher.skills.push({name,level:1});s.teacher.annualGrowth++;if(c.activeSkills.length<4)c.activeSkills.push(name);return {ok:true};}
export function valid(s){const c=s.career;if(c==null)return true;return c.schema===1&&Array.isArray(c.schools)&&c.schools.length===8&&c.schools.every(sc=>M.REGIONS[sc.region]&&typeof sc.id==='string'&&typeof sc.name==='string'&&!/[<>]/.test(sc.name)&&CITIES.includes(sc.city)&&[3,4,5].includes(sc.auditCycle)&&Number.isInteger(sc.lastAudit))&&c.schools.some(x=>x.id===c.schoolId)&&Array.isArray(c.history)&&Array.isArray(c.archives)&&c.archives.length<=100&&c.archives.every(a=>Number.isInteger(a.year)&&Array.isArray(a.students)&&a.students.length>=4&&a.students.length<=28&&a.students.every(st=>typeof st.name==='string'&&!/[<>]/.test(st.name)&&typeof st.id==='string'&&Array.isArray(st.memories))&&a.notes&&Array.isArray(a.lessons))&&['direct','relations','mixed'].includes(c.gradeMode)&&['direct','relations','mixed'].includes(c.jobMode)&&M.SKILLS.includes(c.job)&&Array.isArray(c.activeSkills)&&c.activeSkills.length<=4&&new Set(c.activeSkills).size===c.activeSkills.length&&c.activeSkills.every(n=>s.teacher.skills.some(x=>x.name===n));}
